data.description:
The complete contents for this section — an object for 'profile', an array for every other section. Send it as structured JSON, not as a stringified blob. Required unless `restoreFrom` is given. Shapes (? marks optional):

profile: one object: { name, summary, email?, phone?, location?, linkedIn?, portfolio?, targetRoles?: [string], targetIndustries?: [string], salaryMin?: number, salaryMax?: number }
experience: array of { role, company, startDate: 'YYYY-MM', endDate: 'YYYY-MM' | 'present', summary?, industry?, location?, tags?: [string], achievements: [{ metric, context, impact, keywords?: [string] }] } — achievements are OBJECTS, not strings: metric is the quantified outcome ('cut onboarding from 6 weeks to 9 days'), context is the situation, impact is why it mattered
skills: array of { name, category ('Technical' | 'Leadership' | 'Domain' | …), proficiency?: 1-5, yearsUsed?: number, lastUsed?: 'YYYY' | 'current' }
education: array of { degree, institution, date: 'YYYY' | 'YYYY-MM', honors?, relevantCoursework?: [string], certifications?: [string] }
projects: array of { name, role, description, technologies?: [string], metrics?: [string], outcomes?: [string], url? }
testimonials: array of { source (name and title), relationship ('Direct Manager' | 'Peer' | …), quote, date?, context? }
narrative: array of { topic: 'why_looking' | 'why_left' | 'gap' | 'switch' | 'work_authorization' | 'notice_period' | 'optimizing_for' | 'other', text (the user's own words), updated?: 'YYYY-MM-DD' }
stories: array of { title, situation?, task?, action?, result?, text?, sourceCompany?, sourceRole?, themes?: [string], usedWith?: [{ applicationId?, company?, round?, interviewer?, date? }] }
people: array of { name, howWeKnow?, company?, role?, lastContact?: 'YYYY-MM-DD', offered?, applicationIds?: [string], reconnectEveryDays?: number, notes? }
